"""Morning briefing and end-of-day recap: built from computed data (numbers are never generated by an LLM)."""
import asyncio
import logging
from datetime import datetime, timedelta
from typing import Any
from zoneinfo import ZoneInfo

from jarvis.bus import Bus
from jarvis.station.engine import Station

log = logging.getLogger("jarvis.briefing")
NAMES = {"GBP_USD": "Cable", "EUR_USD": "Euro", "USD_JPY": "Dollar-yen", "XAU_USD": "Gold", "XAG_USD": "Silver", "WTI_USD": "Oil"}


def _day_bounds(now: datetime, offset_days: int = 0) -> tuple[int, int]:
    start = now.replace(hour=0, minute=0, second=0, microsecond=0) + timedelta(days=offset_days)
    return int(start.timestamp() * 1000), int((start + timedelta(days=1)).timestamp() * 1000)


def _events(st: Station, start: int, end: int, tz: ZoneInfo, impacts: tuple[str, ...]) -> list[dict[str, Any]]:
    ccys = {c for ins in st.instruments.values() for c in ins.get("ccy", [])}
    return [{**e, "local": datetime.fromtimestamp(e["time"] / 1000, tz).strftime("%H:%M")} for e in st.ctx.calendar
            if start <= e["time"] < end and e["impact"] in impacts and (e["country"] in ccys or "crude oil" in e["title"].lower())]


def morning(st: Station, now: datetime) -> dict[str, Any]:
    tz = now.tzinfo
    moves = []
    for sym, f in st.frames.items():
        h1 = f.get("HOUR")
        if h1 is not None and len(h1) > 12:
            a, b = float(h1.close.iloc[-13]), float(h1.close.iloc[-1])
            moves.append({"symbol": sym, "pct": round((b / a - 1) * 100, 2), "pips": round((b - a) / st.instruments[sym]["pip"], 1)})
    events = _events(st, *_day_bounds(now), tz, ("High", "Medium"))  # type: ignore[arg-type]
    bias = [{"symbol": s, "call": d["call"], "lean": d["lean"], "confidence": d["confidence"],
             "why": (d["hold_why"] or d["reasons"] or [""])[0]} for s, d in st.calls.items()]
    view = st.ctx.news_view

    text = ["Good morning, sir."]
    if moves:
        text.append("Overnight: " + ", ".join(f"{NAMES[m['symbol']]} {m['pct']:+.2f}%" for m in moves) + ".")
    high = [e for e in events if e["impact"] == "High"]
    text.append("Key events today: " + ", ".join(f"{e['country']} {e['title']} at {e['local']}" for e in high) + "."
                if high else "No high-impact events on the calendar today.")
    if bias:
        text.append("Current calls: " + ", ".join(
            f"{NAMES[b['symbol']]} {b['call']}" + (f" {b['confidence']}" if b["call"] != "HOLD" else "") for b in bias) + ".")
    if view:
        text.append(f"Risk mood is {view['risk_sentiment'].replace('_', '-')}." +
                    (f" {view['geopolitical_alert']}" if view.get("geopolitical_alert") else ""))
    return {"kind": "morning", "title": "Morning briefing", "moves": moves, "events": events, "bias": bias,
            "mood": view.get("risk_sentiment") if view else None, "text": " ".join(text)}


def eod(st: Station, now: datetime) -> dict[str, Any]:
    tz = now.tzinfo
    sigs = st.store.between(*_day_bounds(now))
    closed = [s for s in sigs if s["status"] != "active"]
    wins = [s for s in closed if (s["result_r"] or 0) > 0]
    total_r = round(sum(s["result_r"] or 0 for s in closed), 2)
    tomorrow = _events(st, *_day_bounds(now, 1), tz, ("High",))  # type: ignore[arg-type]
    rows = [{"symbol": s["symbol"], "call": s["call"], "confidence": s["confidence"], "status": s["status"],
             "result_r": s["result_r"]} for s in sigs]

    text = ["End of day recap."]
    if not sigs:
        text.append("No signals were issued today — HOLD was the call.")
    else:
        text.append(f"{len(sigs)} signal{'s' if len(sigs) != 1 else ''} today, {len(closed)} closed: "
                    f"{len(wins)} won, {len(closed) - len(wins)} lost or flat, net {total_r:+.2f}R.")
        text += [f"{NAMES[r['symbol']]} {r['call']} {r['confidence']}: {r['status'].replace('_', ' ')}"
                 + (f" ({r['result_r']:+.2f}R)" if r["result_r"] is not None else "") + "." for r in rows]
    text.append("Tomorrow: " + ", ".join(f"{e['country']} {e['title']} at {e['local']}" for e in tomorrow) + "."
                if tomorrow else "Tomorrow's calendar is quiet.")
    return {"kind": "eod", "title": "End-of-day recap", "signals": rows,
            "accuracy": round(100 * len(wins) / len(closed)) if closed else None, "total_r": total_r,
            "events": tomorrow, "text": " ".join(text)}


def generate(st: Station, bus: Bus, kind: str, tz: str) -> dict[str, Any]:
    now = datetime.now(ZoneInfo(tz))
    b = (morning if kind == "morning" else eod)(st, now)
    b = st.store.add_briefing({**b, "day": now.date().isoformat(), "created": int(now.timestamp() * 1000)})
    bus.publish({**b, "type": "briefing"}, key="briefing")
    log.info("briefing %s generated", kind)
    return b


async def scheduler(st: Station, bus: Bus, cfg: dict[str, Any]) -> None:
    """Fires each briefing once per day at its configured local time (catches up within 2h if the app was closed)."""
    tz = ZoneInfo(cfg["tz"])
    latest = [b for k in ("morning", "eod") for b in st.store.briefings(1, k)]  # not the weekly review
    if latest:
        bus.publish({**max(latest, key=lambda b: b["created"]), "type": "briefing"}, key="briefing")
    while True:
        now = datetime.now(tz)
        for kind in ("morning", "eod"):
            h, m = map(int, cfg[kind].split(":"))
            target = now.replace(hour=h, minute=m, second=0, microsecond=0)
            done = st.store.briefings(1, kind)
            if target <= now < target + timedelta(hours=2) and not (done and done[0]["day"] == now.date().isoformat()):
                generate(st, bus, kind, cfg["tz"])
        await asyncio.sleep(30)
